import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.DnrXFDHb.js";const m=JSON.parse('{"title":"入门路线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1786350421000}'),r={name:"guide/getting-started.md"};function o(s,a,n,h,p,d){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="入门路线" tabindex="-1">入门路线 <a class="header-anchor" href="#入门路线" aria-label="Permalink to &quot;入门路线&quot;">​</a></h1><p>这份知识库按“先建立概念，再理解模型，最后进入工具和专题”的顺序组织。零基础用户不必一次学完所有术语，先知道每一层解决什么问题即可。</p><h2 id="第一步-建立-ai-基础" tabindex="-1">第一步：建立 AI 基础 <a class="header-anchor" href="#第一步-建立-ai-基础" aria-label="Permalink to &quot;第一步：建立 AI 基础&quot;">​</a></h2><p>先阅读 <a href="/ai/basics">AI 基础概念</a>，理解下面几组区别：</p><ul><li>AI、机器学习、深度学习和模型不是同一个概念。</li><li>训练负责形成能力，推理负责在使用时生成结果。</li><li>Token 是文本处理单位，上下文窗口决定模型一次能看到多少信息。</li><li>Embedding 把内容转换成可比较的向量，常用于语义检索。</li></ul><p>这一阶段的目标不是记定义，而是知道模型为什么有能力、成本和边界。</p><h2 id="第二步-理解-llm-理论" tabindex="-1">第二步：理解 LLM 理论 <a class="header-anchor" href="#第二步-理解-llm-理论" aria-label="Permalink to &quot;第二步：理解 LLM 理论&quot;">​</a></h2><p>按顺序阅读：</p><ol><li><a href="/llm/basics">大模型入门</a>：认识 LLM 的能力、幻觉和常见应用形态。</li><li><a href="/llm/transformer">Transformer 直觉</a>：理解 Attention 如何利用上下文。</li><li><a href="/llm/training-alignment">训练、微调与对齐</a>：区分预训练、指令微调、对齐和 RAG。</li><li><a href="/llm/rag-agent">RAG 与 Agent</a>：理解模型如何连接外部知识和工具。</li></ol><p>这一阶段不要求推导公式，但要能说明“模型内部能力、外部资料和工具调用”各自负责什么。</p><h2 id="第三步-学习-prompt-与工具" tabindex="-1">第三步：学习 Prompt 与工具 <a class="header-anchor" href="#第三步-学习-prompt-与工具" aria-label="Permalink to &quot;第三步：学习 Prompt 与工具&quot;">​</a></h2><p>Prompt 不是魔法句式，而是任务说明。阅读 <a href="/prompting/basics">Prompt 入门</a> 后，至少要能写清：</p><ul><li>目标：要模型完成什么。</li><li>背景：模型完成任务需要哪些材料。</li><li>约束：必须遵守什么，不能做什么。</li><li>输出格式：结果应该怎样组织。</li><li>完成标准：如何判断结果可用。</li></ul><p>再通过 <a href="/tools/common-tools">常用工具</a> 区分 Web AI 助手、API、本地模型、RAG/Agent 工具和 AI 绘画界面，不要把工具界面和模型能力混为一谈。</p><h2 id="第四步-进入-ai-绘画专题" tabindex="-1">第四步：进入 AI 绘画专题 <a class="header-anchor" href="#第四步-进入-ai-绘画专题" aria-label="Permalink to &quot;第四步：进入 AI 绘画专题&quot;">​</a></h2><p>如果主要目标是图像生成，再学习：</p><ul><li><a href="/concepts/base-model">底模是什么</a> 与 <a href="/concepts/components">模型组成</a>。</li><li><a href="/concepts/how-it-works">基本原理</a> 与 <a href="/models/ecosystems">常见模型生态</a>。</li><li><a href="/lora/basics">LoRA 入门</a> 和 <a href="/workflows/workflow-vs-template">工作流与模板</a>。</li></ul><p>先跑通最小文生图流程，再逐步加入 LoRA、ControlNet、局部重绘和放大流程。每次只改变少量变量，更容易定位失败原因。</p><h2 id="第五步-建立自己的资料体系" tabindex="-1">第五步：建立自己的资料体系 <a class="header-anchor" href="#第五步-建立自己的资料体系" aria-label="Permalink to &quot;第五步：建立自己的资料体系&quot;">​</a></h2><p>最后浏览 <a href="/resources/websites">常用网站</a>、<a href="/resources/tutorials">精选教程</a> 和 <a href="/glossary">术语表</a>，并为自己使用的重要资源记录：</p><ul><li>来源、版本和更新时间。</li><li>模型卡、许可证与用途限制。</li><li>有效 Prompt、参数和失败案例。</li><li>工作流依赖、节点版本与复现条件。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>只背参数和提示词，不理解模型、数据和工具之间的关系。</li><li>把模型生成的流畅回答当成已经验证的事实。</li><li>认为接入 RAG 或 Agent 后就会自动可靠，忽略检索质量、权限和失败路径。</li><li>一开始就堆复杂工作流，导致问题无法定位。</li><li>忽略数据、模型、素材、API 和平台许可证。</li></ul>',23)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
